@startuml

class Employee {
  + IdentifyingNumber : int
  + Name : string
  + Address : string
}

class PartAccessory {
  + Category : string
  + SerialNumber : string
  + Price : double
}

class Car {
  + LicensePlate : string
  + Make : string
  + Model : string
  + Color : string
}

class Owner {
  + Name : string
  + IdentifyingNumber : int
  + Address : string
  + Phone : string
}

class AssemblyService {
  + KmsAtTime : int
  + WorkHours : float
  + AdmissionDate : date
  + FinishDate : date
}

Owner "1" -- "*" Car : owns

Car "1" -- "*" AssemblyService : undergoes

Employee "1" -- "*" AssemblyService : responsible for

AssemblyService "*" -- "*" PartAccessory : fits

PartAccessory "*" -- "*" Car : fits in models

@enduml

